-- Semeia os 21 processos e as 23 ligações do mapa de processos da casa em
-- `StaffProcess` e `StaffProcessEdge`.
--
-- O QUE SEMEIA
--   Os 21 processos (código, nome, descrição, domínio, nível, tipo, dono,
--   revisado em, tags) e as 23 ligações (de → para, rótulo) de
--   packages/provisioning/src/processos-nebuloz.ts (`PROCESSOS_NEBULOZ`,
--   `LIGACOES_NEBULOZ`), mesmo código e mesmos pares desse arquivo. Gerado a
--   partir dele — se a lista mudar lá, gere este arquivo de novo.
--
-- SÓ CRIA
--   Todo INSERT tem `ON CONFLICT ... DO NOTHING`: rodar de novo, ou rodar
--   depois de um processo/ligação já ter sido editado pela tela, não
--   sobrescreve nada.
--
-- ORDEM DE DEPLOY
--   1. O deploy da Vercel aplica a migration `20260909000000_mapa_de_processos`
--      (cria `StaffProcess` e `StaffProcessEdge`, com RLS — nada disso
--      depende deste script).
--   2. Rode este arquivo no SQL Editor do Supabase.
--   3. Confira o SELECT final: deve devolver `21 | 23`.
--   Até o passo 2 rodar, a tela `/ferramentas/processos` abre vazia com o
--   estado de "nenhum processo" — não quebra.

BEGIN;



COMMIT;

SELECT
  (SELECT count(*) FROM "StaffProcess" WHERE "tenantId"='system') AS processos,
  (SELECT count(*) FROM "StaffProcessEdge" WHERE "tenantId"='system') AS ligacoes;
